    \begin{gather} \|\Delta_{1}^{t+1}\|\leq\alpha\sum_{\tau=0}^{t}(1+\alpha\gamma^{0})^{t-\tau}L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}
