        =\frac{D\rho^{7}}{8}.
    \end{gather*}

We next bound $\mathbb{P}[\mathcal{P}_{2}]$. On $\bar{\mathcal{P}}_{2}$, at least $K/2$ indices in $\{0,\ldots,K-1\}$ satisfy $\mathcal{E}_{2}^{k}$. For sufficiently large $\rho$, $r\geq\rho$ and
    \begin{gather*}
        \ell_s
        \geq
        \frac{d^{2}}{4\alpha r}-6mn\alpha\sigma^{2}r.
    \end{gather*}
    Also, for sufficiently large $\rho$,
    \[
        r\leq\frac{2\rho}{\alpha\epsilon_H}.
    \]
    Using \eqref{eq: Variance}, \eqref{eq: parameters}, and $\epsilon_H^{2}=\epsilon_gL_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}$,
    \begin{gather*}
        \frac{6mn\alpha\sigma^{2}r}{d^{2}/(8\alpha r)}
        =
        \frac{48mn\alpha^{2}\sigma^{2}r^{2}}{d^{2}}
        \leq\frac{6400}{\rho}.
    \end{gather*}
    Hence, there exists $\rho_{\min,7}\geq1$ such that, for all $\rho\geq\rho_{\min,7}$,
    \begin{gather} \ell_s\geq\frac{d^{2}}{8\alpha r}>0.
    \end{gather}
    Consequently,
    \begin{gather} \frac{r}{\ell_s}
        \leq\frac{8\alpha r^{2}}{d^{2}}
        \leq12800L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\epsilon_g^{-2}\rho^{13}.
    \end{gather}

We now construct disjoint saddle blocks. Let $T_{1}$ be the first $k\in\{0,\ldots,K-r\}$ for which $\mathcal{E}_{2}^{k}$ occurs; if no such $k$ exists, set $T_{1}=K$. Recursively, if $T_j=K$, set $Z_j=1$, $\tau_j=0$, and $T_{j+1}=K$. Otherwise define
    \begin{gather*}
        \mathcal{A}_{j}\coloneqq
        \left\{\exists\tau\in\{1,\ldots,r\}:~
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j+\tau})
        -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j})
        \leq-\ell_s\right\},
    \end{gather*}
    \begin{gather*}
        \tau_j\coloneqq
        \begin{cases}
            \min\{\tau\in\{1,\ldots,r\}:
            \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j+\tau})
            -\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{T_j})\leq-\ell_s\},
            & \mathcal{A}_j\text{ occurs},\\
            r, & \text{otherwise},
        \end{cases}
    \end{gather*}
    where
    \begin{gather*}
        Z_j\coloneqq\mathbf{1}_{\mathcal{A}_j}.
    \end{gather*}
    and let $T_{j+1}$ be the first $k\in\{T_j+\tau_j,\ldots,K-r\}$ satisfying $\mathcal{E}_{2}^{k}$; if no such index exists, set $T_{j+1}=K$.

Under $\bar{\mathcal{P}}_{2}$, at most $r$ saddle indices lie in the final $r$ positions, and each selected block contains at most $r$ indices. Therefore the first
    \begin{gather} M\coloneqq\left\lfloor\frac{K/2-r}{r}\right\rfloor
    \end{gather}
    selected blocks are genuine, and \eqref{eq: large rho block conditions} gives
    \begin{gather*}
        M\geq\frac{K}{4r}.
    \end{gather*}

The first term dominates the initial objective gap for sufficiently large $\rho$. Indeed, by \eqref{eq: K} and \eqref{eq: r/ls},
    \begin{gather*}
        \frac{K\ell_s}{32r}
        \geq
        \frac{D\rho}{409600}.
    \end{gather*}
    Moreover, since $K\geq\rho$ and $K\leq D/(L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\epsilon_g^{2}\alpha^{2})+1$,
    \begin{align*}
        mn\alpha\sigma^{2}(K+\sqrt{K\rho}+\rho)
        &\leq3mn\alpha\sigma^{2}K\\
        &=\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}\epsilon_g^{2}}{4}K\\
        &\leq\frac{D}{4}
        +\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha^{2}\epsilon_g^{2}}{4}.
    \end{align*}
    Since $D>0$, by increasing $\rho_{\min,9}$ if necessary, the last term is at most $D/4$, and
    \begin{gather*}
        \frac{K\ell_s}{32r}
        >
        D+mn\alpha\sigma^{2}(K+\sqrt{K\rho}+\rho).
    \end{gather*}
    Thus \eqref{eq: P2 total decrease} would imply
    \[
        \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{K})<\underline{\Psi},
    \]
    contradicting the definition of $\underline{\Psi}$. Hence
    \[
        \bar{\mathcal{P}}_{2}
        \subseteq
        \mathcal{N}_{K}^{c}
        \cup
        \left\{\sum_{j=1}^{M}Z_j<\frac{q_{\rho}M}{2}\right\}.
    \]
    Using \eqref{eq: global noise event}, \eqref{eq: saddle block tail}, and the union bound,
    \begin{gather} \mathbb{P}[\mathcal{P}_{2}]
        \geq1-3\mathrm{e}^{-\rho}.
    \end{gather}

By \eqref{eq: Approximate second order} in
    Proposition~\ref{pro: Approximate second order}, there exists
    \begin{gather*}
        \bar{\alpha}
        \le
        \min\left\{
        \frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}},
        -\frac{2\ln(p)}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}
        \right\}
    \end{gather*}
    such that for any step-size $\alpha \le \bar{\alpha}$,
    with $K$ as per \eqref{eq: Iteration}, and initial condition
    satisfying $\mathbf{x}^{0}=\bm{0}$, it follows that after
    $K$ iterations of \eqref{eq: NLGD with auxiliary function},
    \begin{align*}
        \mathbb{P}\Bigg[
        \exists k\in[0,K],~
        \|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\|
        \le\epsilon_{g}
        ~\land~
        \lambda_{\min}
        \left(
        \nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})
        \right)
        \ge-\epsilon_{H}
        \Bigg]
        \ge 1-p.
    \end{align*}

Then, by Proposition~\ref{pro: Second order relations}
    and Proposition~\ref{pro: NGD interpretation},
    after $K$ iterations of~\eqref{eq: NLGD},
    \begin{multline*}
        \mathbb{P}\Bigg[
        \exists k\in[0,K],~
        \|\sqrt{\hat{\mathbf{L}}}\cdot
        \nabla F(\boldsymbol{\theta}^{k})\|
        \le\epsilon_{g}\\
        \land~
        \forall\,\mathbf{d}\in\mathcal{T},~
        \mathbf{d}^{\top}
        \nabla^{2}F(\boldsymbol{\theta}^{k})
        \mathbf{d}
        \ge
        -
        \frac{\epsilon_{H}}
        {\lambda_{\min}^{+}(\mathbf{L})}
        \|\mathbf{d}\|^{2}
        ~\land~
        (\bm{1}_{m}^{\top}\otimes\mathbf{I}_{n})
        \boldsymbol{\theta}^{k}
        =
        \bm{r}
        \Bigg]
        \ge 1-p,
    \end{multline*}
    as claimed.

